import { useState, useEffect, useRef } from 'react';
import { Outlet } from 'react-router-dom';
import { Sidebar } from './Sidebar';
import { Bell, Check } from 'lucide-react';
import api from '@/services/api';
import { Button } from '@/components/ui/Button';

export default function DashboardLayout() {
    const [notifications, setNotifications] = useState<any[]>([]);
    const [showNotifications, setShowNotifications] = useState(false);
    const notificationRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        fetchNotifications();

        // Close on click outside
        function handleClickOutside(event: MouseEvent) {
            if (notificationRef.current && !notificationRef.current.contains(event.target as Node)) {
                setShowNotifications(false);
            }
        }
        document.addEventListener("mousedown", handleClickOutside);
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        };
    }, []);

    const fetchNotifications = async () => {
        try {
            const res = await api.get('/notifications');
            setNotifications(res.data.data || []);
        } catch (error) {
            console.error("Failed to fetch notifications", error);
        }
    };

    const markAsRead = async (id: string) => {
        try {
            await api.post('/notifications/mark-read', { id });
            setNotifications(notifications.filter(n => n.id !== id));
        } catch (error) {
            console.error("Failed to mark as read", error);
        }
    };

    const unreadCount = notifications.length;

    return (
        <div className="flex min-h-screen w-full bg-muted/40">
            <Sidebar />
            <div className="flex flex-col flex-1 overflow-hidden">
                <header className="flex h-14 items-center gap-4 border-b bg-background px-6 lg:h-[60px] justify-between">
                    <div className="flex-1">
                        {/* Breadcrumbs or Search could go here */}
                    </div>

                    {/* Notification Bell */}
                    <div className="relative" ref={notificationRef}>
                        <Button
                            variant="ghost"
                            size="icon"
                            className="relative"
                            onClick={() => setShowNotifications(!showNotifications)}
                        >
                            <Bell className="h-5 w-5" />
                            {unreadCount > 0 && (
                                <span className="absolute top-1 right-1 h-2 w-2 rounded-full bg-red-600 border border-background"></span>
                            )}
                        </Button>

                        {showNotifications && (
                            <div className="absolute right-0 mt-2 w-80 rounded-md border bg-card shadow-lg z-50">
                                <div className="p-4 border-b">
                                    <h4 className="text-sm font-semibold">Notifications</h4>
                                </div>
                                <div className="max-h-[300px] overflow-y-auto">
                                    {notifications.length === 0 ? (
                                        <div className="p-4 text-center text-sm text-muted-foreground">
                                            No new notifications
                                        </div>
                                    ) : (
                                        <div className="divide-y">
                                            {notifications.map((n) => (
                                                <div key={n.id} className="p-4 hover:bg-muted/50 transition-colors">
                                                    <div className="flex justify-between items-start gap-2">
                                                        <div className="text-sm">
                                                            <p className="font-medium">{n.data?.message || "Notification"}</p>
                                                            <p className="text-xs text-muted-foreground mt-1">{new Date(n.created_at).toLocaleString()}</p>
                                                        </div>
                                                        <button
                                                            onClick={() => markAsRead(n.id)}
                                                            className="text-muted-foreground hover:text-primary"
                                                            title="Mark as read"
                                                        >
                                                            <Check className="h-4 w-4" />
                                                        </button>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>
                </header>
                <main className="flex-1 overflow-y-auto p-6">
                    <Outlet />
                </main>
            </div>
        </div>
    );
}

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import api from "@/services/api";
import { Pencil } from "lucide-react";

export function SalaryManager() {
    const [employees, setEmployees] = useState<any[]>([]);
    const [selectedEmp, setSelectedEmp] = useState<any>(null);
    const [formData, setFormData] = useState({
        basic_salary: '',
        hra: '',
        pf: '',
        transport_allowance: '',
        other_allowances: '',
        tax: '',
        other_deductions: ''
    });
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        api.get('/employees').then(res => setEmployees(res.data.data));
    }, []);

    const handleEdit = (emp: any) => {
        setSelectedEmp(emp);
        // ideally fetch existing salary structure here
        // For now, initializing empty or with employee.salary if available as basic
        setFormData({
            basic_salary: emp.salary || '',
            hra: '0',
            pf: '0',
            transport_allowance: '0',
            other_allowances: '0',
            tax: '0',
            other_deductions: '0'
        });
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        try {
            await api.post(`/salary/${selectedEmp.id}`, formData);
            alert("Salary structure updated!");
            setSelectedEmp(null);
        } catch (error) {
            console.error(error);
            alert("Failed to update salary structure");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="space-y-4">
            <h3 className="text-lg font-medium">Employee Salary Structures</h3>
            <div className="border rounded-md">
                <table className="w-full text-sm">
                    <thead>
                        <tr className="border-b bg-muted/50">
                            <th className="p-3 text-left">Employee</th>
                            <th className="p-3 text-left">Code</th>
                            <th className="p-3 text-right">Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        {employees.map(emp => (
                            <tr key={emp.id} className="border-b">
                                <td className="p-3">{emp.first_name} {emp.last_name}</td>
                                <td className="p-3">{emp.employee_code}</td>
                                <td className="p-3 text-right">
                                    <Dialog open={!!selectedEmp && selectedEmp.id === emp.id} onOpenChange={(open) => !open && setSelectedEmp(null)}>
                                        <DialogTrigger asChild>
                                            <Button variant="outline" size="sm" onClick={() => handleEdit(emp)}>
                                                <Pencil className="h-4 w-4 mr-2" /> Structure
                                            </Button>
                                        </DialogTrigger>
                                        <DialogContent className="sm:max-w-[425px]">
                                            <DialogHeader>
                                                <DialogTitle>Edit Salary Structure: {emp.first_name}</DialogTitle>
                                            </DialogHeader>
                                            <form onSubmit={handleSubmit} className="grid gap-4 py-4">
                                                <div className="grid grid-cols-2 gap-4">
                                                    <div>
                                                        <label className="text-xs">Basic Salary</label>
                                                        <Input type="number" required value={formData.basic_salary} onChange={e => setFormData({ ...formData, basic_salary: e.target.value })} />
                                                    </div>
                                                    <div>
                                                        <label className="text-xs">HRA</label>
                                                        <Input type="number" required value={formData.hra} onChange={e => setFormData({ ...formData, hra: e.target.value })} />
                                                    </div>
                                                </div>
                                                <div className="grid grid-cols-2 gap-4">
                                                    <div>
                                                        <label className="text-xs">Transport</label>
                                                        <Input type="number" value={formData.transport_allowance} onChange={e => setFormData({ ...formData, transport_allowance: e.target.value })} />
                                                    </div>
                                                    <div>
                                                        <label className="text-xs">Other Allowances</label>
                                                        <Input type="number" value={formData.other_allowances} onChange={e => setFormData({ ...formData, other_allowances: e.target.value })} />
                                                    </div>
                                                </div>
                                                <div className="grid grid-cols-2 gap-4">
                                                    <div>
                                                        <label className="text-xs">PF</label>
                                                        <Input type="number" required value={formData.pf} onChange={e => setFormData({ ...formData, pf: e.target.value })} />
                                                    </div>
                                                    <div>
                                                        <label className="text-xs">Tax</label>
                                                        <Input type="number" value={formData.tax} onChange={e => setFormData({ ...formData, tax: e.target.value })} />
                                                    </div>
                                                </div>
                                                <Button type="submit" disabled={loading}>Save Structure</Button>
                                            </form>
                                        </DialogContent>
                                    </Dialog>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
    "inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
    {
        variants: {
            variant: {
                default: "bg-primary text-primary-foreground hover:bg-primary/90",
                destructive:
                    "bg-destructive text-destructive-foreground hover:bg-destructive/90",
                outline:
                    "border border-input bg-background hover:bg-accent hover:text-accent-foreground",
                secondary:
                    "bg-secondary text-secondary-foreground hover:bg-secondary/80",
                ghost: "hover:bg-accent hover:text-accent-foreground",
                link: "text-primary underline-offset-4 hover:underline",
            },
            size: {
                default: "h-10 px-4 py-2",
                sm: "h-9 rounded-md px-3",
                lg: "h-11 rounded-md px-8",
                icon: "h-10 w-10",
            },
        },
        defaultVariants: {
            variant: "default",
            size: "default",
        },
    }
)

export interface ButtonProps
    extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
    asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
    ({ className, variant, size, asChild = false, ...props }, ref) => {
        const Comp = asChild ? Slot : "button"
        return (
            <Comp
                className={cn(buttonVariants({ variant, size, className }))}
                ref={ref}
                {...props}
            />
        )
    }
)
Button.displayName = "Button"

