import React, { createContext, useContext, useState, useEffect } from 'react';
import api from '@/services/api';

interface User {
    id: number;
    name: string;
    email: string;
    roles?: { name: string }[];
}

interface AuthContextType {
    user: User | null;
    token: string | null;
    login: (token: string, user: User) => void;
    logout: () => void;
    isAuthenticated: boolean;
    loading: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [user, setUser] = useState<User | null>(null);
    const [token, setToken] = useState<string | null>(() => localStorage.getItem('token'));
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const initAuth = async () => {
            const storedToken = localStorage.getItem('token');
            if (storedToken) {
                try {
                    const response = await api.get('/user');
                    setUser(response.data);
                } catch (error) {
                    console.error("Failed to fetch user", error);
                    localStorage.removeItem('token');
                    localStorage.removeItem('user');
                    setToken(null);
                    setUser(null);
                }
            }
            setLoading(false);
        };
        initAuth();
    }, []);

    const login = (newToken: string, newUser: User) => {
        setToken(newToken);
        setUser(newUser);
        localStorage.setItem('token', newToken);
        localStorage.setItem('user', JSON.stringify(newUser));
    };

    const logout = () => {
        setToken(null);
        setUser(null);
        localStorage.removeItem('token');
        localStorage.removeItem('user');
    };

    return (
        <AuthContext.Provider value={{ user, token, login, logout, isAuthenticated: !!token, loading }}>
            {children}
        </AuthContext.Provider>
    );
};

// Export hook as default or separate is generally safer but named export should be fine if file is clean.
// The HMR issue often comes from exporting complex logic alongside components.
// We will strictly keep this file identical but ensure clean execution.
export const useAuth = () => {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

import { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table';
import { Plus, Pencil, Trash2, Search, ShieldCheck } from 'lucide-react';
import api from '@/services/api';
import { useAuth } from '@/context/AuthContext';

export default function AdminList() {
    const { user } = useAuth();
    const [users, setUsers] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState("");
    const navigate = useNavigate();

    useEffect(() => {
        fetchUsers();
    }, []);

    const fetchUsers = async () => {
        try {
            const response = await api.get('/users');
            setUsers(response.data.data);
        } catch (error) {
            console.error('Failed to fetch users', error);
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id: number) => {
        if (!confirm('Are you sure you want to delete this user?')) return;
        try {
            await api.delete(`/users/${id}`);
            fetchUsers();
        } catch (error: any) {
            console.error('Failed to delete user', error);
            alert(error.response?.data?.message || 'Failed to delete user');
        }
    };

    const filteredUsers = users.filter(user =>
        user.name.toLowerCase().includes(search.toLowerCase()) ||
        user.email.toLowerCase().includes(search.toLowerCase())
    );

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                    <h1 className="text-2xl font-bold tracking-tight">Admins & Users</h1>
                    <p className="text-muted-foreground mt-1">Manage system administrators and user roles.</p>
                </div>
                <Link to="/admins/create">
                    <Button>
                        <Plus className="mr-2 h-4 w-4" />
                        Create New User
                    </Button>
                </Link>
            </div>

            {/* Search Filter */}
            <div className="flex items-center gap-2 max-w-sm">
                <div className="relative w-full">
                    <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
                    <Input
                        placeholder="Search by name or email..."
                        className="pl-9 bg-card"
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                    />
                </div>
            </div>

            <div className="rounded-lg border bg-card shadow-sm overflow-hidden">
                <Table>
                    <TableHeader className="bg-muted/50">
                        <TableRow>
                            <TableHead className="w-[300px]">User</TableHead>
                            <TableHead>Roles</TableHead>
                            <TableHead>Status</TableHead>
                            <TableHead className="text-right">Actions</TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {loading ? (
                            <TableRow>
                                <TableCell colSpan={5} className="text-center h-32 text-muted-foreground">Loading users...</TableCell>
                            </TableRow>
                        ) : filteredUsers.length === 0 ? (
                            <TableRow>
                                <TableCell colSpan={5} className="text-center h-32 text-muted-foreground">
                                    No users found matching "{search}".
                                </TableCell>
                            </TableRow>
                        ) : (
                            filteredUsers.map((rowUser) => (
                                <TableRow key={rowUser.id} className="hover:bg-muted/50 transition-colors">
                                    <TableCell>
                                        <div className="flex items-center gap-3">
                                            <div className="h-9 w-9 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold">
                                                {rowUser.name.charAt(0).toUpperCase()}
                                            </div>
                                            <div>
                                                <div className="font-medium text-foreground">{rowUser.name}</div>
                                                <div className="text-xs text-muted-foreground">{rowUser.email}</div>
                                            </div>
                                        </div>
                                    </TableCell>
                                    <TableCell>
                                        <div className="flex flex-wrap gap-1">
                                            {rowUser.roles && rowUser.roles.map((r: any) => (
                                                <span key={r.id} className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ring-1 ring-inset ${r.name === 'Super Admin'
                                                    ? 'bg-purple-50 text-purple-700 ring-purple-700/10'
                                                    : r.name === 'Admin'
                                                        ? 'bg-blue-50 text-blue-700 ring-blue-700/10'
                                                        : 'bg-gray-50 text-gray-600 ring-gray-500/10'
                                                    }`}>
                                                    {r.name === 'Super Admin' && <ShieldCheck className="w-3 h-3 mr-1" />}
                                                    {r.name}
                                                </span>
                                            ))}
                                        </div>
                                    </TableCell>
                                    <TableCell>
                                        <span className="inline-flex items-center rounded-full bg-green-50 px-2 py-1 text-xs font-medium text-green-700 ring-1 ring-inset ring-green-600/20">
                                            Active
                                        </span>
                                    </TableCell>
                                    <TableCell className="text-right">
                                        <div className="flex justify-end gap-2">
                                            {/* Logic: 
                                                - Super Admin can edit/delete anyone.
                                                - Admin can edit/delete other Admins/Employees, but NOT Super Admins.
                                                - Cannot delete self.
                                             */}
                                            {(!user.roles.some((r: any) => r.name === 'Super Admin') &&
                                                rowUser.roles.some((r: any) => r.name === 'Super Admin')) ? (
                                                <span className="text-xs text-muted-foreground italic mr-2">Protected</span>
                                            ) : (
                                                <>
                                                    <Button
                                                        variant="outline"
                                                        size="icon"
                                                        className="h-8 w-8"
                                                        onClick={() => navigate(`/admins/edit/${rowUser.id}`)}
                                                        title="Edit User"
                                                    >
                                                        <Pencil className="h-4 w-4" />
                                                    </Button>

                                                    {user.id !== rowUser.id && (
                                                        <Button
                                                            variant="outline"
                                                            size="icon"
                                                            className="h-8 w-8 text-red-600 hover:text-red-700 hover:bg-red-50 border-red-200"
                                                            onClick={() => handleDelete(rowUser.id)}
                                                            title="Delete User"
                                                        >
                                                            <Trash2 className="h-4 w-4" />
                                                        </Button>
                                                    )}
                                                </>
                                            )}
                                        </div>
                                    </TableCell>
                                </TableRow>
                            ))
                        )}
                    </TableBody>
                </Table>
            </div>
        </div>
    );
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import api from '@/services/api';

export default function CreateAdmin() {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        password: '',
        role: 'Admin', // Default to Admin
    });

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        try {
            await api.post('/users', formData);
            navigate('/admins');
        } catch (error: any) {
            console.error('Failed to create user', error);
            alert(error.response?.data?.message || 'Failed to create user');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="max-w-2xl mx-auto">
            <h2 className="text-2xl font-bold tracking-tight mb-6">Create New User</h2>
            <form onSubmit={handleSubmit} className="space-y-6">
                <div className="space-y-2">
                    <label className="text-sm font-medium">Name</label>
                    <Input name="name" required onChange={handleChange} />
                </div>

                <div className="space-y-2">
                    <label className="text-sm font-medium">Email</label>
                    <Input name="email" type="email" required onChange={handleChange} />
                </div>

                <div className="space-y-2">
                    <label className="text-sm font-medium">Password</label>
                    <Input name="password" type="password" required onChange={handleChange} />
                </div>

                <div className="space-y-2">
                    <label className="text-sm font-medium">Role</label>
                    <select
                        name="role"
                        className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                        onChange={handleChange}
                        value={formData.role}
                    >
                        <option value="Admin">Admin</option>
                        <option value="Super Admin">Super Admin</option>
                        <option value="Employee">Employee</option>
                    </select>
                </div>

                <div className="flex justify-end gap-4">
                    <Button type="button" variant="outline" onClick={() => navigate('/admins')}>Cancel</Button>
                    <Button type="submit" disabled={loading}>
                        {loading ? 'Creating...' : 'Create User'}
                    </Button>
                </div>
            </form>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import api from '@/services/api';

export default function EditAdmin() {
    const { id } = useParams();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [fetching, setFetching] = useState(true);
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        password: '',
        role: 'Admin',
    });

    useEffect(() => {
        const loadData = async () => {
            try {
                const response = await api.get(`/users/${id}`);
                const data = response.data.data;
                setFormData({
                    name: data.name,
                    email: data.email,
                    password: '', // Don't populate password
                    role: data.roles?.[0]?.name || 'Admin',
                });
            } catch (error) {
                console.error('Failed to load user', error);
                navigate('/admins');
            } finally {
                setFetching(false);
            }
        };
        loadData();
    }, [id, navigate]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        try {
            await api.put(`/users/${id}`, formData);
            navigate('/admins');
        } catch (error: any) {
            console.error('Failed to update user', error);
            alert(error.response?.data?.message || 'Failed to update user');
        } finally {
            setLoading(false);
        }
    };

    if (fetching) return <div>Loading...</div>;

    return (
        <div className="max-w-2xl mx-auto">
            <h2 className="text-2xl font-bold tracking-tight mb-6">Edit User</h2>
            <form onSubmit={handleSubmit} className="space-y-6">
                <div className="space-y-2">
                    <label className="text-sm font-medium">Name</label>
                    <Input name="name" value={formData.name} required onChange={handleChange} />
                </div>

                <div className="space-y-2">
                    <label className="text-sm font-medium">Email</label>
                    <Input name="email" type="email" value={formData.email} required onChange={handleChange} />
                </div>

                <div className="space-y-2">
                    <label className="text-sm font-medium">Password (Leave blank to keep current)</label>
                    <Input name="password" type="password" onChange={handleChange} />
                </div>

                <div className="space-y-2">
                    <label className="text-sm font-medium">Role</label>
                    <select
                        name="role"
                        className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                        onChange={handleChange}
                        value={formData.role}
                    >
                        <option value="Admin">Admin</option>
                        <option value="Super Admin">Super Admin</option>
                        <option value="Employee">Employee</option>
                    </select>
                </div>

                <div className="flex justify-end gap-4">
                    <Button type="button" variant="outline" onClick={() => navigate('/admins')}>Cancel</Button>
                    <Button type="submit" disabled={loading}>
                        {loading ? 'Updating...' : 'Update User'}
                    </Button>
                </div>
            </form>
        </div>
    );
}

import { useState, useEffect } from "react";
import api from "@/services/api";
import { MapPin } from "lucide-react";
import "leaflet/dist/leaflet.css";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import L from "leaflet";
import icon from "leaflet/dist/images/marker-icon.png";
import iconShadow from "leaflet/dist/images/marker-shadow.png";

// Fix for default marker icon in React-Leaflet
const DefaultIcon = L.icon({
    iconUrl: icon,
    shadowUrl: iconShadow,
    iconSize: [25, 41],
    iconAnchor: [12, 41]
});
L.Marker.prototype.options.icon = DefaultIcon;

export default function AttendanceList() {
    const [attendances, setAttendances] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const now = new Date();
        const start = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
        const end = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];

        api.get(`/reports/attendance?start_date=${start}&end_date=${end}`)
            .then(res => {
                setAttendances(res.data.data);
            })
            .catch(err => console.error(err))
            .finally(() => setLoading(false));
    }, []);

    const formatTime = (isoString: string) => {
        if (!isoString) return "-";
        return new Date(isoString).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    };

    // Filter for valid coordinates only
    const validLocations = attendances.filter(a => a.latitude && a.longitude);
    const centerPosition: [number, number] = validLocations.length > 0
        ? [parseFloat(validLocations[0].latitude), parseFloat(validLocations[0].longitude)]
        : [11.5564, 104.9282]; // Default to Phnom Penh (or generalized center) if no data

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-2xl font-bold tracking-tight text-gray-900">Attendance</h1>
                    <p className="text-muted-foreground mt-1">Manage your organization's HR resources efficiently.</p>
                </div>
            </div>

            {/* Live Location Feed Map */}
            <div className="bg-white p-6 rounded-lg border shadow-sm">
                <h3 className="text-lg font-semibold mb-4 text-gray-900">Live Location Feed (GPS Verified)</h3>

                <div className="h-[400px] rounded-lg overflow-hidden border border-slate-200 z-0 relative">
                    {loading ? (
                        <div className="h-full w-full flex items-center justify-center bg-gray-50 text-gray-400">Loading Map...</div>
                    ) : (
                        <MapContainer center={centerPosition} zoom={13} scrollWheelZoom={false} style={{ height: "100%", width: "100%" }}>
                            <TileLayer
                                attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                            />
                            {validLocations.map((record: any) => (
                                <Marker
                                    key={record.id}
                                    position={[parseFloat(record.latitude), parseFloat(record.longitude)]}
                                >
                                    <Popup>
                                        <div className="text-sm">
                                            <strong className="block mb-1">{record.employee?.user?.name || record.employee?.employee_code}</strong>
                                            <span className="text-gray-500 block">Checked In: {formatTime(record.clock_in)}</span>
                                            <span className="text-gray-500 block">{record.address || 'Unknown Address'}</span>
                                        </div>
                                    </Popup>
                                </Marker>
                            ))}
                        </MapContainer>
                    )}
                </div>

                <div className="mt-2 flex items-center gap-2 text-xs text-muted-foreground">
                    <span className="inline-block h-2 w-2 rounded-full bg-green-500"></span>
                    Active markers show real-time Clock In locations. Click marker for details.
                </div>
            </div>

            {/* Logs Table */}
            <div className="bg-white rounded-lg border shadow-sm overflow-hidden">
                <div className="p-6 border-b">
                    <h3 className="text-lg font-semibold text-gray-900">Daily Attendance Logs</h3>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-gray-50 text-gray-500 font-medium uppercase text-xs">
                            <tr>
                                <th className="px-6 py-4">Employee</th>
                                <th className="px-6 py-4">Date</th>
                                <th className="px-6 py-4">Check In</th>
                                <th className="px-6 py-4">Check Out</th>
                                <th className="px-6 py-4">Location</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {loading ? (
                                <tr><td colSpan={5} className="px-6 py-4 text-center text-muted-foreground">Loading...</td></tr>
                            ) : attendances.length === 0 ? (
                                <tr><td colSpan={5} className="px-6 py-4 text-center text-muted-foreground">No attendance records found for this month.</td></tr>
                            ) : (
                                attendances.map((record: any) => (
                                    <tr key={record.id} className="hover:bg-gray-50 transition-colors">
                                        <td className="px-6 py-4 font-semibold text-gray-900">
                                            {record.employee?.user?.name || record.employee?.employee_code || "N/A"}
                                        </td>
                                        <td className="px-6 py-4 text-gray-600">
                                            {new Date(record.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}
                                        </td>
                                        <td className="px-6 py-4 text-gray-600">
                                            {formatTime(record.clock_in)}
                                        </td>
                                        <td className="px-6 py-4 text-gray-600">
                                            {formatTime(record.clock_out)}
                                        </td>
                                        <td className="px-6 py-4 text-gray-600 flex items-center gap-2">
                                            <MapPin className="h-3 w-3 text-muted-foreground" />
                                            {record.address || "GPS Verified"}
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

import { useState } from 'react';
import { useAuth } from '@/context/AuthContext';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import api from '@/services/api';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Building2, Command } from 'lucide-react';

export default function Login() {
    const { login } = useAuth();
    const navigate = useNavigate();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        try {
            console.log("Attempting login with:", { email });
            const response = await api.post('/login', { email, password });
            console.log("Login successful, response:", response.data);

            const { access_token, user } = response.data;

            if (access_token && user) {
                console.log("Token and user found. Redirecting...");
                login(access_token, user);
                // Force a small delay to allow state to settle if needed, though not usually required
                setTimeout(() => navigate('/dashboard'), 100);
            } else {
                console.error("Missing token or user in response", response.data);
                setError("Login succeeded but received invalid data from server.");
            }

        } catch (err: any) {
            console.error('Login error:', err);
            setError(err.response?.data?.message || 'Invalid email or password');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="w-full lg:grid lg:min-h-screen lg:grid-cols-2">
            <motion.div
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ duration: 0.5 }}
                className="flex items-center justify-center py-12 px-4 sm:px-6 lg:px-8 bg-background"
            >
                <div className="mx-auto w-full max-w-sm space-y-8">
                    <div className="flex flex-col items-center text-center">
                        <div className="flex h-12 w-12 items-center justify-center rounded-lg bg-primary text-primary-foreground mb-4">
                            <Command className="h-6 w-6" />
                        </div>
                        <h2 className="text-3xl font-bold tracking-tight text-foreground">
                            Welcome Back
                        </h2>
                        <p className="mt-2 text-sm text-muted-foreground">
                            Sign in to HRMS Admin Portal
                        </p>
                    </div>

                    <form onSubmit={handleSubmit} className="space-y-6">
                        <div className="space-y-4">
                            <div className="space-y-2">
                                <label htmlFor="email" className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">
                                    Email address
                                </label>
                                <Input
                                    id="email"
                                    type="email"
                                    placeholder="name@company.com"
                                    required
                                    value={email}
                                    onChange={(e) => setEmail(e.target.value)}
                                    className="h-11"
                                />
                            </div>
                            <div className="space-y-2">
                                <div className="flex items-center justify-between">
                                    <label htmlFor="password" className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">
                                        Password
                                    </label>
                                    <a href="#" className="text-sm font-medium text-primary hover:underline">
                                        Forgot password?
                                    </a>
                                </div>
                                <Input
                                    id="password"
                                    type="password"
                                    required
                                    value={password}
                                    onChange={(e) => setPassword(e.target.value)}
                                    className="h-11"
                                />
                            </div>
                        </div>

                        <AnimatePresence>
                            {error && (
                                <motion.div
                                    initial={{ opacity: 0, height: 0 }}
                                    animate={{ opacity: 1, height: 'auto' }}
                                    exit={{ opacity: 0, height: 0 }}
                                    className="text-sm text-red-500 bg-red-50 p-3 rounded-md border border-red-200"
                                >
                                    {error}
                                </motion.div>
                            )}
                        </AnimatePresence>

                        <Button type="submit" className="w-full h-11 text-base shadow-sm" disabled={loading}>
                            {loading ? (
                                <div className="flex items-center gap-2">
                                    <div className="h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent" />
                                    Signing in...
                                </div>
                            ) : 'Sign in'}
                        </Button>
                    </form>

                    <p className="px-8 text-center text-sm text-muted-foreground">
                        Don't have an account?{' '}
                        <a href="#" className="underline underline-offset-4 hover:text-primary">
                            Contact Admin
                        </a>
                    </p>
                </div>
            </motion.div>

            {/* Right Side - Hero Image */}
            <div className="hidden lg:block relative overflow-hidden bg-muted">
                <motion.div
                    initial={{ scale: 1.05 }}
                    animate={{ scale: 1 }}
                    transition={{ duration: 2 }}
                    className="absolute inset-0"
                >
                    <img
                        src="https://images.unsplash.com/photo-1497366216548-37526070297c?q=80&w=2301&auto=format&fit=crop"
                        alt="Modern Office"
                        className="h-full w-full object-cover"
                    />
                    <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-black/0" />
                </motion.div>

                <div className="relative z-10 h-full w-full flex flex-col justify-end p-10 text-white">
                    <motion.div
                        initial={{ y: 20, opacity: 0 }}
                        animate={{ y: 0, opacity: 1 }}
                        transition={{ delay: 0.5, duration: 0.8 }}
                        className="max-w-md"
                    >
                        <div className="mb-4 flex h-10 w-10 items-center justify-center rounded bg-white/10 backdrop-blur-sm border border-white/20">
                            <Building2 className="h-6 w-6 text-white" />
                        </div>
                        <h2 className="text-3xl font-bold leading-tight mb-4">
                            Efficient HR Management for Modern Enterprises
                        </h2>
                        <p className="text-lg text-white/80">
                            Streamline your workforce, manage payroll, and track performance all in one place.
                        </p>
                    </motion.div>
                </div>
            </div>
        </div>
    );
}

