import { useState, useEffect } from 'react';
import { useAuth } from '@/context/AuthContext';
import api from '@/services/api';
import { Button } from '@/components/ui/Button';
import { FileText, Download, Trash2, Upload, Edit } from 'lucide-react';
import UploadDocumentModal from './UploadDocumentModal';
import EditDocumentModal from './EditDocumentModal';

interface Document {
    id: number;
    name: string;
    type: string;
    file_path: string;
    created_at: string;
    employee?: {
        name: string;
    };
}

export default function DocumentList() {
    console.log("Rendering DocumentList");
    const { user } = useAuth();
    const [documents, setDocuments] = useState<Document[]>([]);
    const [loading, setLoading] = useState(true);
    const [isUploadOpen, setIsUploadOpen] = useState(false);
    const [editingDoc, setEditingDoc] = useState<Document | null>(null);

    const isAdmin = user?.roles?.some(r => r.name === 'Super Admin' || r.name === 'Admin');

    useEffect(() => {
        fetchDocuments();
    }, []);

    const fetchDocuments = async () => {
        try {
            const response = await api.get('/documents');
            setDocuments(response.data);
        } catch (error) {
            console.error("Failed to fetch documents", error);
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id: number) => {
        if (!confirm('Are you sure you want to delete this document?')) return;
        try {
            await api.delete(`/documents/${id}`);
            setDocuments(documents.filter(d => d.id !== id));
        } catch (error) {
            console.error("Failed to delete document", error);
        }
    };

    if (loading) return <div>Loading documents...</div>;

    return (
        <div className="space-y-6">
            <UploadDocumentModal
                isOpen={isUploadOpen}
                onClose={() => setIsUploadOpen(false)}
                onSuccess={() => {
                    fetchDocuments();
                    setIsUploadOpen(false);
                }}
            />

            <EditDocumentModal
                isOpen={!!editingDoc}
                onClose={() => setEditingDoc(null)}
                document={editingDoc as any}
                onSuccess={() => {
                    fetchDocuments();
                    setEditingDoc(null);
                }}
            />

            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold tracking-tight">Documents</h1>
                    <p className="text-muted-foreground">Manage and view employee documents.</p>
                </div>
                {isAdmin && (
                    <Button onClick={() => setIsUploadOpen(true)}>
                        <Upload className="mr-2 h-4 w-4" /> Upload Document
                    </Button>
                )}
            </div>

            <div className="rounded-md border bg-white">
                <div className="relative w-full overflow-auto">
                    <table className="w-full caption-bottom text-sm text-left">
                        <thead className="[&_tr]:border-b">
                            <tr className="border-b transition-colors hover:bg-muted/50 data-[state=selected]:bg-muted">
                                <th className="h-12 px-4 align-middle font-medium text-muted-foreground">Name</th>
                                {isAdmin && <th className="h-12 px-4 align-middle font-medium text-muted-foreground">Employee</th>}
                                <th className="h-12 px-4 align-middle font-medium text-muted-foreground">Description / Instructions</th>
                                <th className="h-12 px-4 align-middle font-medium text-muted-foreground">Upload Date</th>
                                <th className="h-12 px-4 align-middle font-medium text-muted-foreground text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="[&_tr:last-child]:border-0">
                            {documents.length === 0 ? (
                                <tr>
                                    <td colSpan={isAdmin ? 5 : 4} className="h-24 text-center">
                                        No documents found.
                                    </td>
                                </tr>
                            ) : (
                                documents.map((doc) => (
                                    <tr key={doc.id} className="border-b transition-colors hover:bg-muted/50">
                                        <td className="p-4 align-middle font-medium">
                                            <div className="flex items-center gap-2">
                                                <FileText className="h-4 w-4 text-primary" />
                                                {doc.name}
                                            </div>
                                        </td>
                                        {isAdmin && <td className="p-4 align-middle">{doc.employee?.name || 'N/A'}</td>}
                                        <td className="p-4 align-middle max-w-[200px] truncate" title={doc.type || ''}>
                                            {doc.type || '-'}
                                        </td>
                                        <td className="p-4 align-middle">{new Date(doc.created_at).toLocaleDateString()}</td>
                                        <td className="p-4 align-middle text-right">
                                            <div className="flex justify-end gap-2">
                                                <Button variant="ghost" size="icon" asChild>
                                                    <a href={`${import.meta.env.VITE_API_URL || 'http://localhost:8000'}/storage/${doc.file_path}`} target="_blank" rel="noreferrer" download>
                                                        <Download className="h-4 w-4" />
                                                    </a>
                                                </Button>
                                                {isAdmin && (
                                                    <>
                                                        <Button variant="ghost" size="icon" className="text-blue-600 hover:text-blue-700 hover:bg-blue-50" onClick={() => setEditingDoc(doc)}>
                                                            <Edit className="h-4 w-4" />
                                                        </Button>
                                                        <Button variant="ghost" size="icon" className="text-red-600 hover:text-red-700 hover:bg-red-50" onClick={() => handleDelete(doc.id)}>
                                                            <Trash2 className="h-4 w-4" />
                                                        </Button>
                                                    </>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

import { useState, useEffect } from 'react';
import api from '@/services/api';
import { Button } from '@/components/ui/Button';
import { X } from 'lucide-react';

interface EditDocumentModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
    document: {
        id: number;
        name: string;
        type: string;
    } | null;
}

export default function EditDocumentModal({ isOpen, onClose, onSuccess, document }: EditDocumentModalProps) {
    const [formData, setFormData] = useState({
        name: '',
        type: '',
    });
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    useEffect(() => {
        if (isOpen && document) {
            setFormData({
                name: document.name || '',
                type: document.type || '',
            });
        }
    }, [isOpen, document]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        if (!formData.name) {
            setError('Please fill in the document name');
            setLoading(false);
            return;
        }

        try {
            await api.put(`/documents/${document?.id}`, {
                name: formData.name,
                type: formData.type
            });
            onSuccess();
            onClose();
        } catch (err: any) {
            setError(err.response?.data?.message || 'Failed to update document');
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen || !document) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
            <div className="w-full max-w-md rounded-lg bg-white p-6 shadow-lg">
                <div className="flex items-center justify-between mb-4">
                    <h2 className="text-xl font-bold">Edit Document</h2>
                    <button onClick={onClose} className="text-gray-500 hover:text-gray-700">
                        <X className="h-5 w-5" />
                    </button>
                </div>

                {error && <div className="mb-4 text-sm text-red-600 bg-red-50 p-2 rounded">{error}</div>}

                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <label className="block text-sm font-medium mb-1">Document Name</label>
                        <input
                            type="text"
                            name="name"
                            value={formData.name}
                            onChange={handleChange}
                            className="w-full rounded-md border p-2"
                            required
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium mb-1">Description / Instructions</label>
                        <textarea
                            name="type"
                            value={formData.type}
                            onChange={handleChange}
                            className="w-full rounded-md border p-2"
                            rows={4}
                            placeholder="Brief instructions for the employee..."
                        />
                    </div>

                    <div className="flex justify-end gap-2 mt-6">
                        <Button type="button" variant="outline" onClick={onClose}>Cancel</Button>
                        <Button type="submit" disabled={loading}>
                            {loading ? 'Saving...' : 'Save Changes'}
                        </Button>
                    </div>
                </form>
            </div>
        </div>
    );
}

import { useState, useEffect } from 'react';
import api from '@/services/api';
import { Button } from '@/components/ui/Button';
import { X } from 'lucide-react';

interface UploadDocumentModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
}

interface Employee {
    id: number;
    name: string;
}

export default function UploadDocumentModal({ isOpen, onClose, onSuccess }: UploadDocumentModalProps) {
    const [employees, setEmployees] = useState<Employee[]>([]);
    const [formData, setFormData] = useState({
        employee_id: '',
        name: '',
        type: '',
        file: null as File | null,
    });
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    useEffect(() => {
        if (isOpen) {
            fetchEmployees();
        }
    }, [isOpen]);

    const fetchEmployees = async () => {
        try {
            const response = await api.get('/employees');
            setEmployees(response.data.data);
        } catch (err) {
            console.error("Failed to fetch employees", err);
        }
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            setFormData(prev => ({ ...prev, file: e.target.files![0] }));
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        if (!formData.employee_id || !formData.name || !formData.file) {
            setError('Please fill in all required fields');
            setLoading(false);
            return;
        }

        const data = new FormData();
        data.append('employee_id', formData.employee_id);
        data.append('name', formData.name);
        data.append('type', formData.type);
        data.append('file', formData.file);

        try {
            await api.post('/documents', data, {
                headers: {
                    'Content-Type': 'multipart/form-data',
                },
            });
            onSuccess();
            onClose();
        } catch (err: any) {
            setError(err.response?.data?.message || 'Failed to upload document');
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
            <div className="w-full max-w-md rounded-lg bg-white p-6 shadow-lg">
                <div className="flex items-center justify-between mb-4">
                    <h2 className="text-xl font-bold">Upload Document</h2>
                    <button onClick={onClose} className="text-gray-500 hover:text-gray-700">
                        <X className="h-5 w-5" />
                    </button>
                </div>

                {error && <div className="mb-4 text-sm text-red-600 bg-red-50 p-2 rounded">{error}</div>}

                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <label className="block text-sm font-medium mb-1">Employee</label>
                        <select
                            name="employee_id"
                            value={formData.employee_id}
                            onChange={handleChange}
                            className="w-full rounded-md border p-2"
                            required
                        >
                            <option value="">Select Employee</option>
                            {employees.map(emp => (
                                <option key={emp.id} value={emp.id}>{emp.name}</option>
                            ))}
                        </select>
                    </div>

                    <div>
                        <label className="block text-sm font-medium mb-1">Document Name</label>
                        <input
                            type="text"
                            name="name"
                            value={formData.name}
                            onChange={handleChange}
                            className="w-full rounded-md border p-2"
                            required
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium mb-1">Description / Instructions</label>
                        <textarea
                            name="type"
                            value={formData.type}
                            onChange={handleChange as any}
                            className="w-full rounded-md border p-2"
                            rows={3}
                            placeholder="Brief instructions for the employee..."
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium mb-1">File</label>
                        <input
                            type="file"
                            onChange={handleFileChange}
                            className="w-full"
                            accept=".pdf,.doc,.docx,.jpg,.png"
                            required
                        />
                    </div>

                    <div className="flex justify-end gap-2 mt-6">
                        <Button type="button" variant="outline" onClick={onClose}>Cancel</Button>
                        <Button type="submit" disabled={loading}>
                            {loading ? 'Uploading...' : 'Upload'}
                        </Button>
                    </div>
                </form>
            </div>
        </div>
    );
}

