import { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import api from '@/services/api';

export default function EditEmployee() {
    const { id } = useParams();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [fetching, setFetching] = useState(true);
    const [formData, setFormData] = useState({
        first_name: '',
        last_name: '',
        email: '',
        employee_code: '',

        job_title: '',
        // branch_id: '',
        // department_id: '',
        department: '',
        joining_date: '',
        salary: '',
        phone: '',
        gender: '',
        address: '',
        dob: ''
    });



    useEffect(() => {
        const loadData = async () => {
            try {
                // Fetch Options
                // Fetch Options Removed
                /*
                const [branchRes, deptRes] = await Promise.all([
                    api.get('/branches'),
                    api.get('/departments')
                ]);
                setBranches(branchRes.data);
                setDepartments(deptRes.data);
                */

                // Fetch Employee
                const response = await api.get(`/employees/${id}`);
                const data = response.data.data;

                setFormData({
                    first_name: data.first_name,
                    last_name: data.last_name,
                    email: data.email || '',
                    employee_code: data.employee_code,
                    job_title: data.job_title || '',
                    // branch_id: data.branch_id || '',
                    // department_id: data.department_id || '',
                    department: data.department || '',
                    joining_date: data.joining_date || '',
                    salary: data.salary || '',
                    phone: data.phone || '',
                    address: data.address || '',
                    gender: data.gender || '',
                    dob: data.dob || ''
                });

            } catch (error) {
                console.error('Failed to load data', error);
                alert('Failed to load data');
                navigate('/employees');
            } finally {
                setFetching(false);
            }
        };

        if (id) loadData();
    }, [id, navigate]);

    const [profilePicture, setProfilePicture] = useState<File | null>(null);

    // ... useEffect unchanged ...

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            setProfilePicture(e.target.files[0]);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        try {
            const data = new FormData();

            // Using Post method spoofing for Laravel to handle file uploads in PUT context
            data.append('_method', 'PUT');

            Object.keys(formData).forEach(key => {
                // For update, exclude empty password if not changing
                const val = formData[key as keyof typeof formData];
                // If null, don't append. If empty and not password, append.
                if (val !== null) {
                    data.append(key, val);
                }
            });

            if (profilePicture) {
                data.append('profile_picture', profilePicture);
            }

            // Using POST with _method=PUT
            await api.post(`/employees/${id}`, data, {
                headers: { 'Content-Type': 'multipart/form-data' }
            });
            navigate('/employees');
        } catch (error: any) {
            console.error('Failed to update employee', error);
            alert(error.response?.data?.message || 'Failed to update employee');
        } finally {
            setLoading(false);
        }
    };

    if (fetching) return <div>Loading...</div>;

    return (
        <div className="max-w-3xl mx-auto">
            <h2 className="text-2xl font-bold tracking-tight mb-6">Edit Employee</h2>
            <form onSubmit={handleSubmit} className="space-y-6">

                {/* Profile Picture Input */}
                <div className="space-y-2">
                    <label className="text-sm font-medium">Profile Picture</label>
                    <Input type="file" onChange={handleFileChange} accept="image/*" />
                    <p className="text-xs text-muted-foreground">Leave blank to keep current picture.</p>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-sm font-medium">First Name</label>
                        <Input name="first_name" value={formData.first_name} required onChange={handleChange} />
                    </div>
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Last Name</label>
                        <Input name="last_name" value={formData.last_name} required onChange={handleChange} />
                    </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Email</label>
                        <Input name="email" type="email" value={formData.email} required onChange={handleChange} />
                    </div>
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Phone Number</label>
                        <Input name="phone" value={formData.phone} onChange={handleChange} />
                    </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Date of Birth</label>
                        <Input name="dob" type="date" value={formData.dob} onChange={handleChange} />
                    </div>
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Gender</label>
                        <select
                            name="gender"
                            className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                            onChange={handleChange}
                            value={formData.gender}
                        >
                            <option value="">Select Gender</option>
                            <option value="Male">Male</option>
                            <option value="Female">Female</option>
                            <option value="Other">Other</option>
                        </select>
                    </div>
                </div>

                <div className="space-y-2">
                    <label className="text-sm font-medium">Address</label>
                    <textarea
                        name="address"
                        className="flex min-h-[80px] w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                        value={formData.address}
                        onChange={handleChange}
                    />
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Employee Code</label>
                        <Input name="employee_code" value={formData.employee_code} required onChange={handleChange} />
                    </div>
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Joining Date</label>
                        <Input name="joining_date" type="date" value={formData.joining_date} required onChange={handleChange} />
                    </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Job Title</label>
                        <Input name="job_title" value={formData.job_title} required onChange={handleChange} />
                    </div>
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Department</label>
                        <Input name="department" value={formData.department || ''} onChange={handleChange} placeholder="e.g. Engineering" />
                    </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-sm font-medium">Salary (Monthly)</label>
                        <Input name="salary" type="number" value={formData.salary} onChange={handleChange} />
                    </div>
                </div>

                <div className="flex justify-end gap-4">
                    <Button type="button" variant="outline" onClick={() => navigate('/employees')}>Cancel</Button>
                    <Button type="submit" disabled={loading}>
                        {loading ? 'Updating...' : 'Update Employee'}
                    </Button>
                </div>
            </form>
        </div>
    );
}

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Pencil, Trash2, Plus, Search } from 'lucide-react';

import api from '@/services/api';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table';

interface Employee {
    id: number;
    employee_code: string;
    first_name: string;
    last_name: string;
    email?: string;
    phone?: string;
    job_title?: string;
    profile_picture_url?: string;
}

export default function EmployeeList() {
    const navigate = useNavigate();
    const [employees, setEmployees] = useState<Employee[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');

    useEffect(() => {
        fetchEmployees();
    }, []);

    const handleDelete = async (id: number) => {
        if (!window.confirm("Are you sure you want to delete this employee?")) return;

        try {
            await api.delete(`/employees/${id}`);
            setEmployees(prev => prev.filter(emp => emp.id !== id));
        } catch (error: any) {
            console.error("Failed to delete employee", error);
            const message = error.response?.data?.message || "Failed to delete employee";
            alert(message);
        }
    };

    const fetchEmployees = async () => {
        try {
            const response = await api.get('/employees');
            setEmployees(response.data.data); // Assuming Laravel Resource returns { data: [...] }
        } catch (error) {
            console.error('Failed to fetch employees', error);
        } finally {
            setLoading(false);
        }
    };

    const filteredEmployees = employees.filter(emp =>
        emp.first_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        emp.last_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        emp.employee_code.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight">Employees</h2>
                    <p className="text-muted-foreground">Manage your organization's workforce.</p>
                </div>
                <Button className="gap-2" onClick={() => navigate('/employees/create')}>
                    <Plus className="h-4 w-4" /> Add Employee
                </Button>
            </div>

            <div className="flex items-center py-4">
                <div className="relative max-w-sm w-full">
                    <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
                    <Input
                        placeholder="Search employees..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="pl-8"
                    />
                </div>
            </div>

            <div className="rounded-md border bg-card">
                <Table>
                    <TableHeader>
                        <TableRow>
                            <TableHead className="w-[300px]">Name</TableHead>
                            <TableHead className="w-[100px]">Code</TableHead>
                            <TableHead className="w-[200px]">Job Title</TableHead>
                            <TableHead className="w-[200px]">Email</TableHead>
                            <TableHead className="w-[150px]">Phone</TableHead>
                            <TableHead className="text-right w-[100px]">Actions</TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {loading ? (
                            <TableRow>
                                <TableCell colSpan={6} className="h-24 text-center">
                                    Loading...
                                </TableCell>
                            </TableRow>
                        ) : filteredEmployees.length === 0 ? (
                            <TableRow>
                                <TableCell colSpan={6} className="h-24 text-center">
                                    No employees found.
                                </TableCell>
                            </TableRow>
                        ) : (
                            filteredEmployees.map((employee) => (
                                <TableRow key={employee.id}>
                                    <TableCell>
                                        <div className="flex items-center gap-3">
                                            <div className="h-10 w-10 rounded-full overflow-hidden bg-gray-100 border border-gray-200 flex items-center justify-center">
                                                {employee.profile_picture_url ? (
                                                    <img src={employee.profile_picture_url} alt="" className="h-full w-full object-cover" />
                                                ) : (
                                                    <span className="text-sm font-medium text-gray-500">{employee.first_name[0]}{employee.last_name[0]}</span>
                                                )}
                                            </div>
                                            <div className="font-medium">{employee.first_name} {employee.last_name}</div>
                                        </div>
                                    </TableCell>
                                    <TableCell className="font-medium">{employee.employee_code}</TableCell>
                                    <TableCell>{employee.job_title || '-'}</TableCell>
                                    <TableCell>{employee.email || '-'}</TableCell>
                                    <TableCell>{employee.phone || '-'}</TableCell>
                                    <TableCell className="text-right">
                                        <div className="flex justify-end gap-2">
                                            <Button
                                                variant="ghost"
                                                size="icon"
                                                onClick={() => navigate(`/employees/edit/${employee.id}`)}
                                                title="Edit"
                                            >
                                                <Pencil className="h-4 w-4 text-blue-500" />
                                            </Button>
                                            <Button
                                                variant="ghost"
                                                size="icon"
                                                onClick={() => handleDelete(employee.id)}
                                                title="Delete"
                                            >
                                                <Trash2 className="h-4 w-4 text-red-500" />
                                            </Button>
                                        </div>
                                    </TableCell>
                                </TableRow>
                            ))
                        )}
                    </TableBody>
                </Table>
            </div>
        </div >
    );
}

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogFooter,
} from "@/components/ui/dialog";
import api from "@/services/api";
import { Trash2, Plus, Calendar, PartyPopper } from "lucide-react";

interface Holiday {
    id: number;
    name: string;
    date: string;
    type: 'public' | 'company';
    description?: string;
}

export default function HolidayList() {
    const [holidays, setHolidays] = useState<Holiday[]>([]);
    const [loading, setLoading] = useState(true);
    const [isCreateOpen, setIsCreateOpen] = useState(false);

    // Form State
    const [newName, setNewName] = useState('');
    const [newDate, setNewDate] = useState('');
    const [newType, setNewType] = useState<'public' | 'company'>('public');

    const fetchHolidays = async () => {
        setLoading(true);
        try {
            const res = await api.get('/holidays');
            // ApiResponse: { status: true, data: [...] }
            setHolidays(res.data.data || res.data);
        } catch (error) {
            console.error("Failed to fetch holidays", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchHolidays();
    }, []);

    const handleCreate = async () => {
        try {
            await api.post('/holidays', {
                name: newName,
                date: newDate,
                type: newType
            });
            setNewName('');
            setNewDate('');
            setIsCreateOpen(false);
            fetchHolidays();
        } catch (error) {
            alert("Failed to create holiday");
        }
    };

    const handleDelete = async (id: number) => {
        if (!confirm("Delete this holiday?")) return;
        try {
            await api.delete(`/holidays/${id}`);
            setHolidays(holidays.filter(h => h.id !== id));
        } catch (error) {
            alert("Failed to delete holiday");
        }
    };

    // Calculate upcoming holiday for the highlight card
    const nextHoliday = holidays
        .filter(h => new Date(h.date) >= new Date())
        .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())[0];

    return (
        <div className="space-y-8">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-2xl font-bold tracking-tight">Holidays & Announcements</h1>
                    <p className="text-muted-foreground mt-1">Manage public holidays and company events.</p>
                </div>
                <Button onClick={() => setIsCreateOpen(true)}>
                    <Plus className="mr-2 h-4 w-4" /> Add Holiday
                </Button>
            </div>

            {/* Highlight Card for Next Holiday */}
            {nextHoliday && (
                <div className="bg-gradient-to-r from-blue-500 to-blue-600 rounded-xl p-6 text-white shadow-lg flex items-center justify-between">
                    <div>
                        <div className="flex items-center gap-2 text-blue-100 text-sm font-medium mb-1">
                            <PartyPopper className="h-4 w-4" />
                            <span>Upcoming Holiday</span>
                        </div>
                        <h2 className="text-3xl font-bold">{nextHoliday.name}</h2>
                        <p className="text-blue-100 mt-1 flex items-center gap-2">
                            <Calendar className="h-4 w-4" />
                            {new Date(nextHoliday.date).toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
                        </p>
                    </div>
                    <div className="bg-white/20 backdrop-blur-sm px-4 py-2 rounded-lg text-center min-w-[100px]">
                        <span className="block text-2xl font-bold">
                            {Math.ceil((new Date(nextHoliday.date).getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24))}
                        </span>
                        <span className="text-xs text-blue-100 uppercase font-medium">Days Left</span>
                    </div>
                </div>
            )}

            <div className="rounded-xl border bg-card shadow-sm overflow-hidden">
                <div className="p-6 border-b bg-muted/30">
                    <h3 className="font-semibold text-lg">All Holidays</h3>
                    <p className="text-sm text-muted-foreground">List of all registered holidays and events for this year.</p>
                </div>
                <Table>
                    <TableHeader className="bg-muted/50">
                        <TableRow>
                            <TableHead className="pl-6">Date</TableHead>
                            <TableHead>Holiday Name</TableHead>
                            <TableHead>Type</TableHead>
                            <TableHead className="text-right pr-6">Actions</TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {loading ? (
                            <TableRow><TableCell colSpan={4} className="text-center h-32">Loading...</TableCell></TableRow>
                        ) : holidays.length === 0 ? (
                            <TableRow><TableCell colSpan={4} className="text-center h-32 text-muted-foreground">No holidays found.</TableCell></TableRow>
                        ) : (
                            holidays.map((holiday) => (
                                <TableRow key={holiday.id} className="hover:bg-muted/50">
                                    <TableCell className="font-medium pl-6">
                                        <div className="flex items-center gap-3">
                                            <div className="h-8 w-8 rounded-full bg-blue-50 flex items-center justify-center text-blue-600">
                                                <Calendar className="h-4 w-4" />
                                            </div>
                                            <span className="text-base">
                                                {new Date(holiday.date).toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' })}
                                            </span>
                                            <span className="text-xs text-muted-foreground ml-1">
                                                {new Date(holiday.date).getFullYear()}
                                            </span>
                                        </div>
                                    </TableCell>
                                    <TableCell className="text-base">{holiday.name}</TableCell>
                                    <TableCell>
                                        <span className={`px-2.5 py-0.5 rounded-full text-xs font-semibold uppercase tracking-wide border ${holiday.type === 'public' ? 'bg-blue-50 text-blue-700 border-blue-200' : 'bg-purple-50 text-purple-700 border-purple-200'}`}>
                                            {holiday.type}
                                        </span>
                                    </TableCell>
                                    <TableCell className="text-right pr-6">
                                        <Button size="icon" variant="ghost" className="text-muted-foreground hover:text-red-600 hover:bg-red-50" onClick={() => handleDelete(holiday.id)}>
                                            <Trash2 className="h-4 w-4" />
                                        </Button>
                                    </TableCell>
                                </TableRow>
                            ))
                        )}
                    </TableBody>
                </Table>
            </div>

            <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>Add New Holiday</DialogTitle>
                    </DialogHeader>
                    <div className="space-y-4 py-4">
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Name</label>
                            <Input value={newName} onChange={e => setNewName(e.target.value)} placeholder="e.g. New Year" />
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Date</label>
                            <Input type="date" value={newDate} onChange={e => setNewDate(e.target.value)} />
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Type</label>
                            <select
                                className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
                                value={newType}
                                onChange={e => setNewType(e.target.value as any)}
                            >
                                <option value="public">Public Holiday</option>
                                <option value="company">Company Event</option>
                            </select>
                        </div>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setIsCreateOpen(false)}>Cancel</Button>
                        <Button onClick={handleCreate}>Save Holiday</Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/Button";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import api from "@/services/api";
import { Check, X } from "lucide-react";

export default function LeaveList() {
    const [leaves, setLeaves] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState<'all' | 'pending' | 'approved' | 'rejected'>('all');

    const fetchLeaves = async () => {
        setLoading(true);
        try {
            const res = await api.get('/leaves');
            // Backend returns direct array for index()
            setLeaves(Array.isArray(res.data) ? res.data : (res.data.data || []));
        } catch (error) {
            console.error("Failed to fetch leaves", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchLeaves();
    }, []);

    const handleStatusUpdate = async (id: number, status: 'approved' | 'rejected') => {
        let rejection_reason = '';

        if (status === 'rejected') {
            const reason = prompt("Please enter a reason for rejection:");
            if (reason === null) return; // Cancelled
            if (reason.trim() === '') {
                alert("Rejection reason is required.");
                return;
            }
            rejection_reason = reason;
        } else {
            if (!confirm(`Are you sure you want to ${status} this leave request?`)) return;
        }

        try {
            await api.put(`/leaves/${id}/status`, { status, rejection_reason });
            // Optimistic update
            setLeaves(leaves.map(l => l.id === id ? { ...l, status } : l));
        } catch (error: any) {
            console.error("Failed to update status", error);
            const msg = error.response?.data?.message || "Failed to update status";
            alert(msg);
        }
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'approved': return 'text-green-600 bg-green-50 px-2 py-1 rounded-full text-xs font-medium';
            case 'rejected': return 'text-red-600 bg-red-50 px-2 py-1 rounded-full text-xs font-medium';
            case 'pending': return 'text-yellow-600 bg-yellow-50 px-2 py-1 rounded-full text-xs font-medium';
            default: return 'text-gray-600';
        }
    };

    const filteredLeaves = leaves.filter(l => filter === 'all' || l.status === filter);

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-2xl font-bold tracking-tight">Leave Management</h1>
                    <p className="text-muted-foreground mt-1">Review and manage employee leave requests.</p>
                </div>
                <div className="flex gap-2">
                    {/* Future Add Button */}
                </div>
            </div>

            {/* Filters */}
            <div className="flex items-center gap-2 bg-muted/50 p-1 rounded-lg w-fit">
                {(['all', 'pending', 'approved', 'rejected'] as const).map((f) => (
                    <button
                        key={f}
                        onClick={() => setFilter(f)}
                        className={`px-4 py-1.5 text-sm font-medium rounded-md capitalize transition-all ${filter === f ? 'bg-background shadow text-foreground' : 'text-muted-foreground hover:text-foreground'
                            }`}
                    >
                        {f}
                    </button>
                ))}
            </div>

            <div className="rounded-lg border bg-card shadow-sm overflow-hidden">
                <Table>
                    <TableHeader className="bg-muted/50">
                        <TableRow>
                            <TableHead>Employee</TableHead>
                            <TableHead>Leave Type</TableHead>
                            <TableHead>Duration</TableHead>
                            <TableHead>Dates</TableHead>
                            <TableHead>Reason</TableHead>
                            <TableHead>Status</TableHead>
                            <TableHead className="text-right">Actions</TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {loading ? (
                            <TableRow>
                                <TableCell colSpan={7} className="text-center h-32 text-muted-foreground">Loading requests...</TableCell>
                            </TableRow>
                        ) : filteredLeaves.length === 0 ? (
                            <TableRow>
                                <TableCell colSpan={7} className="text-center h-32 text-muted-foreground">
                                    No {filter === 'all' ? '' : filter} leave requests found.
                                </TableCell>
                            </TableRow>
                        ) : (
                            filteredLeaves.map((leave) => (
                                <TableRow key={leave.id} className="hover:bg-muted/50 transition-colors">
                                    <TableCell className="font-medium">
                                        <div className="flex items-center gap-3">
                                            <div className="h-8 w-8 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold text-xs">
                                                {(leave.user?.name?.[0] || leave.employee?.first_name?.[0] || "U").toUpperCase()}
                                            </div>
                                            <div>
                                                <div>{leave.user?.name || `${leave.employee?.first_name} ${leave.employee?.last_name}`}</div>
                                                <div className="text-xs text-muted-foreground">{leave.employee?.employee_code}</div>
                                            </div>
                                        </div>
                                    </TableCell>
                                    <TableCell className="font-medium text-muted-foreground">
                                        {leave.leave_type?.name}
                                    </TableCell>
                                    <TableCell>
                                        <span className="font-mono">{leave.days_count}</span> days
                                    </TableCell>
                                    <TableCell className="text-sm text-muted-foreground">
                                        <span>{new Date(leave.start_date).toLocaleDateString()} - {new Date(leave.end_date).toLocaleDateString()}</span>
                                    </TableCell>
                                    <TableCell>
                                        <div className="max-w-[200px] truncate text-muted-foreground" title={leave.reason}>
                                            {leave.reason}
                                        </div>
                                    </TableCell>
                                    <TableCell>
                                        <span className={getStatusColor(leave.status)}>
                                            {leave.status}
                                        </span>
                                    </TableCell>
                                    <TableCell className="text-right">
                                        {leave.status === 'pending' && (
                                            <div className="flex justify-end gap-2">
                                                <Button size="icon" variant="outline" className="h-8 w-8 text-green-600 hover:text-green-700 hover:bg-green-50 border-green-200" onClick={() => handleStatusUpdate(leave.id, 'approved')} title="Approve">
                                                    <Check className="h-4 w-4" />
                                                </Button>
                                                <Button size="icon" variant="outline" className="h-8 w-8 text-red-600 hover:text-red-700 hover:bg-red-50 border-red-200" onClick={() => handleStatusUpdate(leave.id, 'rejected')} title="Reject">
                                                    <X className="h-4 w-4" />
                                                </Button>
                                            </div>
                                        )}
                                    </TableCell>
                                </TableRow>
                            ))
                        )}
                    </TableBody>
                </Table>
            </div>
        </div>
    );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/context/AuthContext";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { User, Mail, Phone, MapPin, Building, Briefcase, Calendar } from "lucide-react";
import api from "@/services/api";

export default function Profile() {
    const { user } = useAuth();
    const [employee, setEmployee] = useState<any>(null);
    const [loading, setLoading] = useState(true);

    // Password Update
    const [passwords, setPasswords] = useState({ current: "", new: "", confirm: "" });

    useEffect(() => {
        fetchProfile();
    }, [user]);

    const fetchProfile = async () => {
        try {
            const res = await api.get('/user');
            // Check if user has employee profile linked
            if (res.data.data?.employee) {
                setEmployee(res.data.data.employee);
            } else if (res.data.employee) {
                // Handle different API structure if needed
                setEmployee(res.data.employee);
            } else if (user?.email) {
                // Try fetching employee by email if not directly attached
                const empRes = await api.get('/employees?email=' + user.email);
                if (empRes.data.data && empRes.data.data.length > 0) {
                    setEmployee(empRes.data.data[0]);
                }
            }
        } catch (error) {
            console.error("Failed to fetch profile", error);
        } finally {
            setLoading(false);
        }
    };

    const handlePasswordUpdate = async () => {
        if (passwords.new !== passwords.confirm) {
            alert("New passwords do not match");
            return;
        }
        try {
            await api.put('/user/password', {
                current_password: passwords.current,
                new_password: passwords.new
            });
            alert("Password updated successfully");
            setPasswords({ current: "", new: "", confirm: "" });
        } catch (error) {
            console.error("Failed to update password", error);
            alert("Failed to update password");
        }
    };

    if (loading) return <div>Loading profile...</div>;

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-2xl font-bold tracking-tight">My Profile</h1>
                <p className="text-muted-foreground">Manage your personal information and security.</p>
            </div>

            <div className="grid gap-6 md:grid-cols-2">
                {/* Personal Info Card */}
                <div className="space-y-6">
                    <div className="p-6 bg-card rounded-lg border shadow-sm">
                        <div className="flex items-center gap-4 mb-6">
                            <div className="h-16 w-16 rounded-full bg-primary/10 flex items-center justify-center text-primary text-2xl font-bold border-2 border-primary">
                                {user?.name?.[0]?.toUpperCase()}
                            </div>
                            <div>
                                <h2 className="text-xl font-bold">{user?.name}</h2>
                                <p className="text-muted-foreground flex items-center gap-1 text-sm">
                                    <Mail className="h-3 w-3" /> {user?.email}
                                </p>
                                <div className="flex gap-2 mt-2">
                                    {user?.roles?.map((r: any) => (
                                        <span key={r.name} className="px-2 py-0.5 bg-blue-100 text-blue-700 text-xs rounded-full font-medium">
                                            {r.name}
                                        </span>
                                    ))}
                                </div>
                            </div>
                        </div>

                        {employee ? (
                            <div className="space-y-4">
                                <h3 className="font-semibold border-b pb-2">Employee Details</h3>
                                <div className="grid grid-cols-2 gap-4 text-sm">
                                    <div>
                                        <span className="text-muted-foreground block text-xs">Employee ID</span>
                                        <span className="font-medium flex items-center gap-1"><User className="h-3 w-3" /> {employee.employee_code}</span>
                                    </div>
                                    <div>
                                        <span className="text-muted-foreground block text-xs">Phone</span>
                                        <span className="font-medium flex items-center gap-1"><Phone className="h-3 w-3" /> {employee.phone}</span>
                                    </div>
                                    <div>
                                        <span className="text-muted-foreground block text-xs">Branch</span>
                                        <span className="font-medium flex items-center gap-1"><Building className="h-3 w-3" /> {employee.branch?.name}</span>
                                    </div>
                                    <div>
                                        <span className="text-muted-foreground block text-xs">Department</span>
                                        <span className="font-medium flex items-center gap-1"><Briefcase className="h-3 w-3" /> {employee.department?.name}</span>
                                    </div>
                                    <div>
                                        <span className="text-muted-foreground block text-xs">Joined</span>
                                        <span className="font-medium flex items-center gap-1"><Calendar className="h-3 w-3" /> {employee.joining_date}</span>
                                    </div>
                                    <div>
                                        <span className="text-muted-foreground block text-xs">Address</span>
                                        <span className="font-medium flex items-center gap-1"><MapPin className="h-3 w-3" /> {employee.address}</span>
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <div className="p-4 bg-yellow-50 text-yellow-800 rounded text-sm">
                                No linked employee profile found. You are signed in as a System User.
                            </div>
                        )}
                    </div>
                </div>

                {/* Security Settings */}
                <div className="space-y-6">
                    <div className="p-6 bg-card rounded-lg border shadow-sm">
                        <h3 className="text-lg font-semibold mb-4">Security</h3>
                        <div className="space-y-4">
                            <div className="space-y-2">
                                <label className="text-sm font-medium">Current Password</label>
                                <Input
                                    type="password"
                                    value={passwords.current}
                                    onChange={(e) => setPasswords({ ...passwords, current: e.target.value })}
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-sm font-medium">New Password</label>
                                <Input
                                    type="password"
                                    value={passwords.new}
                                    onChange={(e) => setPasswords({ ...passwords, new: e.target.value })}
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-sm font-medium">Confirm New Password</label>
                                <Input
                                    type="password"
                                    value={passwords.confirm}
                                    onChange={(e) => setPasswords({ ...passwords, confirm: e.target.value })}
                                />
                            </div>
                            <Button onClick={handlePasswordUpdate}>Update Password</Button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

import { useState } from "react";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { Download, Calendar, DollarSign } from "lucide-react";
import api from "@/services/api";

import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

export default function Reports() {
    const [activeTab, setActiveTab] = useState("attendance");
    const [dateRange, setDateRange] = useState({ start: "", end: "" });
    const [reportData, setReportData] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);

    const generateReport = async () => {
        setLoading(true);
        try {
            // Determine endpoint based on tab
            const endpoint = activeTab === "attendance" ? "/reports/attendance" : "/reports/payroll";
            const params = activeTab === "attendance"
                ? { start_date: dateRange.start || new Date().toISOString().split('T')[0], end_date: dateRange.end || new Date().toISOString().split('T')[0] }
                : {
                    month: dateRange.start ? new Date(dateRange.start).getMonth() + 1 : new Date().getMonth() + 1,
                    year: dateRange.start ? new Date(dateRange.start).getFullYear() : new Date().getFullYear()
                };

            const res = await api.get(endpoint, { params });
            setReportData(res.data.data || res.data);
        } catch (error) {
            console.error("Failed to fetch report", error);
            // setReportData([]); // Keep previous data or clear?
        } finally {
            setLoading(false);
        }
    };

    const exportToCSV = () => {
        if (reportData.length === 0) return;

        let headers = [];
        let rows = [];

        if (activeTab === "attendance") {
            headers = ["Date", "Employee", "Status", "Clock In", "Clock Out", "Hours", "Address"];
            rows = reportData.map(row => [
                new Date(row.date).toLocaleDateString(),
                row.employee?.user?.name || `${row.employee?.first_name} ${row.employee?.last_name}`,
                row.status,
                row.clock_in ? new Date(row.clock_in).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '-',
                row.clock_out ? new Date(row.clock_out).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '-',
                row.hours_worked || '-',
                row.address || 'GPS Verified'
            ]);
        } else {
            headers = ["Employee", "Month", "Basic Salary", "Total Allowances", "Total Deductions", "Net Salary"];
            rows = reportData.map(row => [
                row.employee?.user?.name || `${row.employee?.first_name} ${row.employee?.last_name}`,
                row.month + '/' + row.year,
                row.basic_salary,
                row.total_allowances,
                row.total_deductions,
                row.net_salary
            ]);
        }

        const csvContent = [headers.join(","), ...rows.map(e => e.join(","))].join("\n");
        const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.setAttribute("download", `${activeTab}_report_${new Date().toISOString().split('T')[0]}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const exportToPDF = () => {
        if (reportData.length === 0) return;

        const doc = new jsPDF();

        // Add Title
        doc.setFontSize(18);
        doc.text(activeTab === "attendance" ? "Attendance Report" : "Payroll Summary", 14, 22);

        doc.setFontSize(11);
        doc.setTextColor(100);
        doc.text(`Generated on: ${new Date().toLocaleDateString()}`, 14, 30);

        let head = [];
        let body = [];

        if (activeTab === "attendance") {
            head = [["Date", "Employee", "Status", "In", "Out", "Hrs", "Location"]];
            body = reportData.map(row => [
                new Date(row.date).toLocaleDateString(),
                row.employee?.user?.name || `${row.employee?.first_name} ${row.employee?.last_name}`,
                row.status,
                row.clock_in ? new Date(row.clock_in).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '-',
                row.clock_out ? new Date(row.clock_out).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '-',
                row.hours_worked || '-',
                row.address || 'GPS'
            ]);
        } else {
            head = [["Employee", "period", "Basic", "Allowances", "Deductions", "Net Salary"]];
            body = reportData.map(row => [
                row.employee?.user?.name || `${row.employee?.first_name} ${row.employee?.last_name}`,
                row.month + '/' + row.year,
                `$${parseFloat(row.basic_salary).toLocaleString()}`,
                `+$${parseFloat(row.total_allowances).toLocaleString()}`,
                `-$${parseFloat(row.total_deductions).toLocaleString()}`,
                `$${parseFloat(row.net_salary).toLocaleString()}`
            ]);
        }

        autoTable(doc, {
            startY: 40,
            head: head,
            body: body,
            theme: 'grid',
            headStyles: { fillColor: [41, 128, 185], textColor: 255 },
            styles: { fontSize: 8 }
        });

        doc.save(`${activeTab}_report_${new Date().toISOString().split('T')[0]}.pdf`);
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-2xl font-bold tracking-tight">Reports & Analytics</h1>
                    <p className="text-muted-foreground mt-1">Generate and export system reports.</p>
                </div>
                <div className="flex gap-2">
                    <Button variant="outline" onClick={exportToCSV} disabled={reportData.length === 0}>
                        <Download className="mr-2 h-4 w-4" /> Export CSV
                    </Button>
                    <Button variant="outline" onClick={exportToPDF} disabled={reportData.length === 0}>
                        <Download className="mr-2 h-4 w-4" /> Export PDF
                    </Button>
                </div>
            </div>

            {/* Tabs */}
            <div className="flex border-b">
                <button
                    onClick={() => { setActiveTab("attendance"); setReportData([]); }}
                    className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${activeTab === "attendance" ? "border-primary text-primary" : "border-transparent text-muted-foreground hover:text-foreground"
                        }`}
                >
                    <div className="flex items-center gap-2">
                        <Calendar className="h-4 w-4" /> Attendance Report
                    </div>
                </button>
                <button
                    onClick={() => { setActiveTab("payroll"); setReportData([]); }}
                    className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${activeTab === "payroll" ? "border-primary text-primary" : "border-transparent text-muted-foreground hover:text-foreground"
                        }`}
                >
                    <div className="flex items-center gap-2">
                        <DollarSign className="h-4 w-4" /> Payroll Summary
                    </div>
                </button>
            </div>

            {/* Filters */}
            <div className="flex items-end gap-4 bg-card p-4 rounded-lg border shadow-sm">
                <div className="grid gap-2">
                    <label className="text-sm font-medium">Start Date</label>
                    <Input
                        type="date"
                        value={dateRange.start}
                        onChange={(e) => setDateRange({ ...dateRange, start: e.target.value })}
                    />
                </div>
                <div className="grid gap-2">
                    <label className="text-sm font-medium">End Date</label>
                    <Input
                        type="date"
                        value={dateRange.end}
                        onChange={(e) => setDateRange({ ...dateRange, end: e.target.value })}
                    />
                </div>
                <Button onClick={generateReport} disabled={loading}>
                    {loading ? "Generating..." : "Generate Report"}
                </Button>
            </div>

            {/* Report Table */}
            <div className="rounded-lg border bg-card shadow-sm overflow-hidden">
                <Table>
                    <TableHeader className="bg-muted/50">
                        {activeTab === "attendance" ? (
                            <TableRow>
                                <TableHead>Date</TableHead>
                                <TableHead>Employee</TableHead>
                                <TableHead>Status</TableHead>
                                <TableHead>Clock In</TableHead>
                                <TableHead>Clock Out</TableHead>
                                <TableHead>Hours</TableHead>
                            </TableRow>
                        ) : (
                            <TableRow>
                                <TableHead>Employee</TableHead>
                                <TableHead>Month</TableHead>
                                <TableHead>Basic Salary</TableHead>
                                <TableHead>Total Earnings</TableHead>
                                <TableHead>Total Deductions</TableHead>
                                <TableHead className="text-right">Net Salary</TableHead>
                            </TableRow>
                        )}
                    </TableHeader>
                    <TableBody>
                        {loading ? (
                            <TableRow>
                                <TableCell colSpan={6} className="text-center h-32 text-muted-foreground">Fetching data...</TableCell>
                            </TableRow>
                        ) : reportData.length === 0 ? (
                            <TableRow>
                                <TableCell colSpan={6} className="text-center h-32 text-muted-foreground">
                                    No records found. Select dates and click Generate.
                                </TableCell>
                            </TableRow>
                        ) : (
                            reportData.map((row: any, i) => (
                                <TableRow key={i} className="hover:bg-muted/50">
                                    {activeTab === "attendance" ? (
                                        <>
                                            <TableCell>{new Date(row.date).toLocaleDateString()}</TableCell>
                                            <TableCell className="font-medium">{row.employee?.user?.name || `${row.employee?.first_name} ${row.employee?.last_name}`}</TableCell>
                                            <TableCell>
                                                <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${row.status === 'Present' ? 'bg-green-50 text-green-700' :
                                                    row.status === 'Absent' ? 'bg-red-50 text-red-700' : 'bg-yellow-50 text-yellow-700'
                                                    }`}>
                                                    {row.status}
                                                </span>
                                            </TableCell>
                                            <TableCell>{row.clock_in ? new Date(row.clock_in).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) : '-'}</TableCell>
                                            <TableCell>{row.clock_out ? new Date(row.clock_out).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) : '-'}</TableCell>
                                            <TableCell>{row.hours_worked || '-'}</TableCell>
                                        </>
                                    ) : (
                                        <>
                                            <TableCell className="font-medium">{row.employee?.first_name} {row.employee?.last_name}</TableCell>
                                            <TableCell>{row.month}</TableCell>
                                            <TableCell>{parseFloat(row.basic_salary).toLocaleString()}</TableCell>
                                            <TableCell className="text-green-600">+{parseFloat(row.total_allowances).toLocaleString()}</TableCell>
                                            <TableCell className="text-red-600">-{parseFloat(row.total_deductions).toLocaleString()}</TableCell>
                                            <TableCell className="text-right font-bold">{parseFloat(row.net_salary).toLocaleString()}</TableCell>
                                        </>
                                    )}
                                </TableRow>
                            ))
                        )}
                    </TableBody>
                </Table>
            </div>
        </div>
    );
}

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
    DialogFooter,
} from "@/components/ui/dialog";
import api from "@/services/api";
import { Trash2, Plus, Building2, Calendar, Lock, Moon, Sun } from "lucide-react";
import { useAuth } from "@/context/AuthContext";

export default function Settings() {
    const { user } = useAuth();
    const [passwords, setPasswords] = useState({ current: "", new: "", confirm: "" });

    const handlePasswordUpdate = async () => {
        if (passwords.new !== passwords.confirm) {
            alert("New passwords do not match");
            return;
        }
        try {
            await api.put('/user/password', {
                current_password: passwords.current,
                new_password: passwords.new
            });
            alert("Password updated successfully");
            setPasswords({ current: "", new: "", confirm: "" });
        } catch (error) {
            console.error("Failed to update password", error);
            alert("Failed to update password");
        }
    };
    const isSuperAdmin = user?.roles?.some(r => r.name === 'Super Admin');
    const [activeTab, setActiveTab] = useState(isSuperAdmin ? "general" : "appearance"); // Default to appearance for demo
    const [leaveTypes, setLeaveTypes] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);

    // New Leave Type Form
    const [newType, setNewType] = useState({ name: "", days_allowed: "" });
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const [isDarkMode, setIsDarkMode] = useState(false);

    useEffect(() => {
        // Check initial theme
        const isDark = document.documentElement.classList.contains('dark');
        setIsDarkMode(isDark);
    }, []);

    useEffect(() => {
        if (activeTab === "leaves") {
            fetchLeaveTypes();
        }
    }, [activeTab]);

    const toggleTheme = () => {
        const newMode = !isDarkMode;
        setIsDarkMode(newMode);
        if (newMode) {
            document.documentElement.classList.add('dark');
            localStorage.setItem('theme', 'dark');
        } else {
            document.documentElement.classList.remove('dark');
            localStorage.setItem('theme', 'light');
        }
    };

    const fetchLeaveTypes = async () => {
        setLoading(true);
        try {
            const res = await api.get('/leave-types');
            setLeaveTypes(res.data);
        } catch (error) {
            console.error("Failed to fetch leave types", error);
        } finally {
            setLoading(false);
        }
    };

    const handleCreateLeaveType = async () => {
        try {
            await api.post('/leave-types', newType);
            setNewType({ name: "", days_allowed: "" });
            setIsDialogOpen(false);
            fetchLeaveTypes();
        } catch (error) {
            console.error("Failed to create leave type", error);
            alert("Failed to create leave type");
        }
    };

    const handleDeleteLeaveType = async (id: number) => {
        if (!confirm("Are you sure?")) return;
        try {
            await api.delete(`/leave-types/${id}`);
            fetchLeaveTypes();
        } catch (error) {
            console.error("Failed to delete leave type", error);
        }
    };

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-2xl font-bold tracking-tight">Settings</h1>
                <p className="text-muted-foreground mt-1">Manage system configurations and preferences.</p>
            </div>

            {/* Tabs Navigation */}
            <div className="flex border-b">
                {isSuperAdmin && (
                    <button
                        onClick={() => setActiveTab("general")}
                        className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${activeTab === "general" ? "border-primary text-primary" : "border-transparent text-muted-foreground hover:text-foreground"
                            }`}
                    >
                        <div className="flex items-center gap-2">
                            <Building2 className="h-4 w-4" /> General
                        </div>
                    </button>
                )}
                <button
                    onClick={() => setActiveTab("appearance")}
                    className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${activeTab === "appearance" ? "border-primary text-primary" : "border-transparent text-muted-foreground hover:text-foreground"
                        }`}
                >
                    <div className="flex items-center gap-2">
                        <Moon className="h-4 w-4" /> Appearance
                    </div>
                </button>
                <button
                    onClick={() => setActiveTab('leaves')}
                    className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${activeTab === 'leaves' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground'}`}
                >
                    <div className="flex items-center gap-2">
                        <Calendar className="h-4 w-4" /> Leaves
                    </div>
                </button>
                <button
                    onClick={() => setActiveTab('security')}
                    className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${activeTab === 'security' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground'}`}
                >
                    <div className="flex items-center gap-2">
                        <Lock className="h-4 w-4" /> Security
                    </div>
                </button>
            </div>

            {/* Tab Content */}
            <div className="p-1">
                {activeTab === "general" && (
                    <div className="max-w-xl space-y-4">
                        <div className="bg-card p-6 rounded-lg border shadow-sm">
                            <h3 className="text-lg font-medium mb-4">Organization Profile</h3>
                            <div className="grid gap-4">
                                <div className="grid gap-2">
                                    <label className="text-sm font-medium">Company Name</label>
                                    <Input defaultValue="Nova HRMS" readOnly className="bg-muted" />
                                </div>
                                <div className="grid gap-2">
                                    <label className="text-sm font-medium">Contact Email</label>
                                    <Input defaultValue="admin@novahrms.com" readOnly className="bg-muted" />
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {activeTab === "appearance" && (
                    <div className="max-w-xl space-y-4">
                        <div className="bg-card p-6 rounded-lg border shadow-sm">
                            <h3 className="text-lg font-medium mb-4">Theme Preferences</h3>
                            <div className="flex items-center justify-between">
                                <div className="space-y-0.5">
                                    <label className="text-sm font-medium">Dark Mode</label>
                                    <p className="text-muted-foreground text-sm">Enable dark mode for a better viewing experience at night.</p>
                                </div>
                                <Button
                                    variant={isDarkMode ? "default" : "outline"}
                                    onClick={toggleTheme}
                                    className="w-[100px]"
                                >
                                    {isDarkMode ? (
                                        <div className="flex items-center gap-2"><Moon className="h-4 w-4" /> ON</div>
                                    ) : (
                                        <div className="flex items-center gap-2"><Sun className="h-4 w-4" /> OFF</div>
                                    )}
                                </Button>
                            </div>
                        </div>
                    </div>
                )}

                {activeTab === "leaves" && (
                    <div className="space-y-4">
                        <div className="flex justify-between items-center">
                            <h3 className="text-lg font-medium">Leave Types Configuration</h3>
                            <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
                                <DialogTrigger asChild>
                                    <Button>
                                        <Plus className="h-4 w-4 mr-2" /> Add Leave Type
                                    </Button>
                                </DialogTrigger>
                                <DialogContent>
                                    <DialogHeader>
                                        <DialogTitle>Add New Leave Type</DialogTitle>
                                    </DialogHeader>
                                    <div className="grid gap-4 py-4">
                                        <div className="grid gap-2">
                                            <label className="text-sm font-medium">Name</label>
                                            <Input
                                                placeholder="e.g. Sick Leave"
                                                value={newType.name}
                                                onChange={(e) => setNewType({ ...newType, name: e.target.value })}
                                            />
                                        </div>
                                        <div className="grid gap-2">
                                            <label className="text-sm font-medium">Days Allowed (per year)</label>
                                            <Input
                                                type="number"
                                                placeholder="12"
                                                value={newType.days_allowed}
                                                onChange={(e) => setNewType({ ...newType, days_allowed: e.target.value })}
                                            />
                                        </div>
                                    </div>
                                    <DialogFooter>
                                        <Button onClick={handleCreateLeaveType}>Save Leave Type</Button>
                                    </DialogFooter>
                                </DialogContent>
                            </Dialog>
                        </div>

                        <div className="rounded-md border bg-card shadow-sm">
                            <Table>
                                <TableHeader>
                                    <TableRow>
                                        <TableHead>Leave Type Name</TableHead>
                                        <TableHead>Days Allowed</TableHead>
                                        <TableHead className="text-right">Actions</TableHead>
                                    </TableRow>
                                </TableHeader>
                                <TableBody>
                                    {loading ? (
                                        <TableRow><TableCell colSpan={3} className="text-center h-24">Loading...</TableCell></TableRow>
                                    ) : leaveTypes.length === 0 ? (
                                        <TableRow><TableCell colSpan={3} className="text-center h-24 text-muted-foreground">No leave types defined.</TableCell></TableRow>
                                    ) : (
                                        leaveTypes.map((type) => (
                                            <TableRow key={type.id}>
                                                <TableCell className="font-medium">{type.name}</TableCell>
                                                <TableCell>{type.days_allowed} days / year</TableCell>
                                                <TableCell className="text-right">
                                                    <Button
                                                        variant="ghost"
                                                        size="icon"
                                                        className="text-red-500 hover:text-red-600 hover:bg-red-50"
                                                        onClick={() => handleDeleteLeaveType(type.id)}
                                                    >
                                                        <Trash2 className="h-4 w-4" />
                                                    </Button>
                                                </TableCell>
                                            </TableRow>
                                        ))
                                    )}
                                </TableBody>
                            </Table>
                        </div>
                    </div>
                )}
                {activeTab === 'security' && (
                    <div className="max-w-md space-y-6">
                        <div className="bg-card p-6 rounded-lg border shadow-sm">
                            <h3 className="text-lg font-medium mb-4">Change Password</h3>
                            <div className="space-y-4">
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Current Password</label>
                                    <Input
                                        type="password"
                                        value={passwords.current}
                                        onChange={(e) => setPasswords({ ...passwords, current: e.target.value })}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">New Password</label>
                                    <Input
                                        type="password"
                                        value={passwords.new}
                                        onChange={(e) => setPasswords({ ...passwords, new: e.target.value })}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Confirm New Password</label>
                                    <Input
                                        type="password"
                                        value={passwords.confirm}
                                        onChange={(e) => setPasswords({ ...passwords, confirm: e.target.value })}
                                    />
                                </div>
                                <Button onClick={handlePasswordUpdate}>Update Password</Button>
                            </div>
                        </div>
                    </div>
                )}

            </div>
        </div>
    );
}

