import { useState, useEffect } from "react";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogFooter,
} from "@/components/ui/dialog";
import { Plus, CheckCircle2, Clock, AlertCircle, Calendar } from "lucide-react";
import api from "@/services/api";
import { useAuth } from "@/context/AuthContext";

export default function TaskList() {
    const { user } = useAuth();
    const [tasks, setTasks] = useState<any[]>([]);
    const [employees, setEmployees] = useState<any[]>([]);
    const [isCreateOpen, setIsCreateOpen] = useState(false);

    // Form State
    const [newTask, setNewTask] = useState({
        title: "",
        description: "",
        assigned_to: "",
        priority: "medium",
        due_date: ""
    });

    useEffect(() => {
        fetchTasks();
        if (user?.roles?.some(r => r.name !== 'Employee')) {
            fetchEmployees();
        }
    }, [user]);

    const fetchTasks = async () => {
        try {
            const res = await api.get('/tasks');
            // ApiResponse: { status: true, data: [...] or { data: [...] } }
            // If paginated, data is in res.data.data.data
            // If simple array, data is in res.data.data

            const payload = res.data.data;
            if (Array.isArray(payload)) {
                setTasks(payload);
            } else if (payload?.data && Array.isArray(payload.data)) {
                setTasks(payload.data);
            } else {
                setTasks([]);
            }
        } catch (error) {
            console.error("Failed to fetch tasks", error);
        }
    };

    const fetchEmployees = async () => {
        try {
            const res = await api.get('/employees');
            const data = res.data.data;
            // Handle pagination if present
            setEmployees(Array.isArray(data) ? data : (data?.data || []));
        } catch (error) {
            console.error("Failed to fetch employees", error);
        }
    };

    const handleCreate = async () => {
        try {
            const res = await api.post('/tasks', newTask);
            setTasks([res.data.data, ...tasks]);
            setIsCreateOpen(false);
            setNewTask({ title: "", description: "", assigned_to: "", priority: "medium", due_date: "" });
        } catch (error) {
            console.error("Failed to create task", error);
            alert("Failed to create task");
        }
    };

    const updateStatus = async (id: number, status: string) => {
        try {
            await api.put(`/tasks/${id}`, { status });
            setTasks(tasks.map(t => t.id === id ? { ...t, status } : t));
        } catch (error) {
            console.error("Failed to update status", error);
        }
    };

    const handleDelete = async (id: number) => {
        if (!confirm("Delete this task?")) return;
        try {
            await api.delete(`/tasks/${id}`);
            setTasks(tasks.filter(t => t.id !== id));
        } catch (error) {
            console.error("Failed to delete task", error);
        }
    };



    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-2xl font-bold tracking-tight">Task Management</h1>
                    <p className="text-muted-foreground">Assign and track employee tasks.</p>
                </div>
                {!user?.roles?.some(r => r.name === 'Employee') && (
                    <Button onClick={() => setIsCreateOpen(true)}>
                        <Plus className="mr-2 h-4 w-4" /> New Task
                    </Button>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {/* Pending */}
                <TaskColumn
                    title="Pending"
                    icon={Clock}
                    tasks={tasks.filter(t => t.status === 'pending')}
                    color="bg-yellow-50 border-yellow-100"
                    onUpdateStatus={updateStatus}
                    onDelete={handleDelete}
                    canManage={!user?.roles?.some(r => r.name === 'Employee')}
                />
                {/* In Progress */}
                <TaskColumn
                    title="In Progress"
                    icon={AlertCircle}
                    tasks={tasks.filter(t => t.status === 'in_progress')}
                    color="bg-blue-50 border-blue-100"
                    onUpdateStatus={updateStatus}
                    onDelete={handleDelete}
                    canManage={!user?.roles?.some(r => r.name === 'Employee')}
                />
                {/* Completed */}
                <TaskColumn
                    title="Completed"
                    icon={CheckCircle2}
                    tasks={tasks.filter(t => t.status === 'completed')}
                    color="bg-green-50 border-green-100"
                    onUpdateStatus={updateStatus}
                    onDelete={handleDelete}
                    canManage={!user?.roles?.some(r => r.name === 'Employee')}
                />
            </div>

            <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>Create New Task</DialogTitle>
                    </DialogHeader>
                    <div className="space-y-4 py-4">
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Title</label>
                            <Input
                                value={newTask.title}
                                onChange={(e) => setNewTask({ ...newTask, title: e.target.value })}
                                placeholder="Task title"
                            />
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Description</label>
                            <Input
                                value={newTask.description}
                                onChange={(e) => setNewTask({ ...newTask, description: e.target.value })}
                                placeholder="Description"
                            />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <label className="text-sm font-medium">Assign To</label>
                                <select
                                    className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
                                    value={newTask.assigned_to}
                                    onChange={(e) => setNewTask({ ...newTask, assigned_to: e.target.value })}
                                >
                                    <option value="">Select Employee</option>
                                    {employees.map(e => (
                                        <option key={e.id} value={e.id}>{e.first_name} {e.last_name}</option>
                                    ))}
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-sm font-medium">Priority</label>
                                <select
                                    className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
                                    value={newTask.priority}
                                    onChange={(e) => setNewTask({ ...newTask, priority: e.target.value })}
                                >
                                    <option value="low">Low</option>
                                    <option value="medium">Medium</option>
                                    <option value="high">High</option>
                                </select>
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Due Date</label>
                            <Input
                                type="date"
                                value={newTask.due_date}
                                onChange={(e) => setNewTask({ ...newTask, due_date: e.target.value })}
                            />
                        </div>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setIsCreateOpen(false)}>Cancel</Button>
                        <Button onClick={handleCreate}>Create Task</Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}

function TaskColumn({ title, icon: Icon, tasks, color, onUpdateStatus, onDelete, canManage }: any) {
    return (
        <div className={`rounded-lg border p-4 ${color} h-full`}>
            <div className="flex items-center gap-2 mb-4">
                <Icon className="h-5 w-5 opacity-70" />
                <h3 className="font-semibold">{title}</h3>
                <span className="ml-auto bg-white/50 px-2 py-0.5 rounded text-xs font-medium border border-black/5">
                    {tasks.length}
                </span>
            </div>

            <div className="space-y-3">
                {tasks.map((task: any) => (
                    <div key={task.id} className="bg-white p-3 rounded-md shadow-sm border border-black/5 hover:shadow transition-shadow">
                        <div className="flex justify-between items-start mb-2">
                            <h4 className="font-medium text-sm line-clamp-2">{task.title}</h4>
                            <div className={`text-[10px] px-1.5 py-0.5 rounded uppercase font-bold border ${task.priority === 'high' ? 'bg-red-50 text-red-600 border-red-100' :
                                task.priority === 'medium' ? 'bg-yellow-50 text-yellow-600 border-yellow-100' :
                                    'bg-blue-50 text-blue-600 border-blue-100'
                                }`}>
                                {task.priority}
                            </div>
                        </div>

                        <p className="text-xs text-muted-foreground mb-3 line-clamp-2">{task.description}</p>

                        <div className="flex items-center justify-between text-xs text-muted-foreground mt-2 pt-2 border-t border-dashed">
                            <div className="flex items-center gap-1" title="Due Date">
                                <Calendar className="h-3 w-3" />
                                <span>{task.due_date}</span>
                            </div>
                            {task.employee && (
                                <div className="font-medium text-foreground">
                                    {task.employee.first_name} {task.employee.last_name?.[0]}.
                                </div>
                            )}
                        </div>

                        {/* Actions */}
                        <div className="mt-3 flex gap-2">
                            {/* Only Employees (who do the work) should see the Start/Complete buttons */}
                            {task.status !== 'completed' && !canManage && (
                                <Button
                                    size="sm"
                                    variant="outline"
                                    className="h-6 text-[10px] px-2 w-full"
                                    onClick={() => onUpdateStatus(task.id, task.status === 'pending' ? 'in_progress' : 'completed')}
                                >
                                    {task.status === 'pending' ? 'Start Task' : 'Mark Complete'}
                                </Button>
                            )}
                            {canManage && (
                                <Button
                                    size="sm"
                                    variant="ghost"
                                    className="h-6 w-6 p-0 text-red-500 hover:text-red-700 hover:bg-red-50"
                                    onClick={() => onDelete(task.id)}
                                >
                                    ×
                                </Button>
                            )}
                        </div>
                    </div>
                ))}
                {tasks.length === 0 && (
                    <div className="text-center py-8 text-xs text-muted-foreground opacity-70">
                        No tasks
                    </div>
                )}
            </div>
        </div>
    );
}
